"""Migration of the seven OPP_MASTER validation rules from opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(image: dict | None, column: str) -> Any:
    """Return a field value, treating missing fields and None as empty strings."""
    if image is None:
        return ""
    value = image.get(column, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    """
    Compare YYYYMMDD dates using legacy ordering semantics.

    Any ordering comparison involving the 00000000 sentinel is false.
    """
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    # INSERT OLD references resolve to empty values. UPDATE uses the supplied image.
    old_image = old if event == "UPDATE" else None

    amt = _value(record, "AMT")
    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")
    old_stat_cd = _value(old_image, "STAT_CD")

    # OPP-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amt, 0)) >= Decimal(0)):
            errors.append(_error("E3001", "Amount negative"))

    # OPP-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0))):
            errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_error("E3003", "Lost reason required"))

    # OPP-004: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and close_dt == "00000000")):
            errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005: UPDATE
    if event == "UPDATE":
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        stage = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage == Decimal(10))
            or (stat_cd == "Q" and stage == Decimal(25))
            or (stat_cd == "N" and stage == Decimal(60))
            or (stat_cd == "W" and stage == Decimal(100))
            or (stat_cd == "L" and stage == Decimal(0))
        )
        if not valid_stage:
            errors.append(
                _error("E3006", "Stage percent inconsistent with status")
            )

    # OPP-007: INSERT, WARN
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_gte(close_dt, today)):
            errors.append(_error("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True exactly when at least one collected failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
